Section BND.
  Context {HCEIL : HeapCeil}.
Definition dof_bnd (lo shi spa E : Z) : Prop :=
  lo + 4144 <= spa /\ aceil <= lo /\ spa + 352 <= shi /\ 0 <= spa /\ spa + 288 < 2^64
  /\ 6811648 <= E /\ E + 24 <= aceil /\ E + 24 < 2^47 /\ 0 < E
  /\ 140735332483072 <= aceil <= 140737479966720
  /\ bv_unsigned (Z_to_bv 64 spa) = spa /\ spa mod 32 = 0.
End BND.

Ltac dbnd_lia BND := clear - BND; unfold dof_bnd in BND; lia.

